// Portfolio content, bilingual. Facts come from the Behance project data, the project images and Or's CV.
// The content itself lives in content/projects.json and content/categories.json (editable in Pages CMS — see .pages.yml).
// Every project belongs to exactly one category. The order on the site is computed here (see `inCategory`); the array
// order in projects.json (Or's Behance order) only breaks ties. Image ids refer to src/data/images.json (generated by
// scripts/images.mjs).
import type { T } from '../i18n';
import projectData from '../content/projects.json';
import categoryData from '../content/categories.json';

export type Img = { id: string; alt: T; focus?: string }; // focus: object-position when the image is cropped
export type Detail = { label: T; body: T; colors?: string[] };

export type Project = {
  slug: string;
  title: T;
  subtitle: T;
  client: T;
  year: string;
  category: string; // slug of a category in content/categories.json
  discipline: T[];
  tools: string[];
  accent: string; // taken from each project's own palette
  cover: Img; // home page
  hero: Img; // top of the project page
  intro: T[];
  details?: Detail[];
  gallery: Img[]; // laid out automatically: wide images full width, tall/square images in rows
  behance: string;
};

// lead: the project whose cover stands for the category on the home page's category wheel
export type Category = { slug: string; title: T; intro: T; lead: string };

/** Every cover on the site is shown in Behance's project-cover frame (808 × 632); `cover.focus` picks what a crop keeps. */
export const coverFrame = '808 / 632';

const all = projectData as Project[];
export const categories = categoryData as Category[];

// Study projects share a "client" label but are not a series, so they are never grouped together.
const UNGROUPED = ['Study project'];

/** A category's projects, newest first; several projects for the same client stay together, placed by the newest one. */
export const inCategory = (slug: string) => {
  const groups = new Map<string, Project[]>();
  for (const p of all.filter((x) => x.category === slug)) {
    const key = UNGROUPED.includes(p.client.en) ? p.slug : p.client.en;
    groups.set(key, [...(groups.get(key) ?? []), p]);
  }
  const newest = (g: Project[]) => Math.max(...g.map((p) => +p.year));
  // Array.sort is stable, so equal years keep the projects.json order
  return [...groups.values()]
    .map((g) => g.sort((a, b) => +b.year - +a.year))
    .sort((a, b) => newest(b) - newest(a))
    .flat();
};

/** Every project in site order: category by category. */
export const projects = categories.flatMap((c) => inCategory(c.slug));

export const bySlug = (slug: string) => projects.find((p) => p.slug === slug);
export const categoryOf = (p: Project) => categories.find((c) => c.slug === p.category)!;
export const leadOf = (c: Category) => bySlug(c.lead)!;

// Fail the build on content mistakes the CMS can't prevent.
for (const p of all) if (!categories.some((c) => c.slug === p.category)) throw new Error(`Project "${p.slug}" has an unknown category "${p.category}"`);
for (const c of categories) {
  if (all.some((p) => p.slug === c.slug)) throw new Error(`Category "${c.slug}" has the same address as a project (/work/${c.slug}/)`);
  if (!all.some((p) => p.category === c.slug)) throw new Error(`Category "${c.slug}" has no projects`);
  if (!all.some((p) => p.slug === c.lead && p.category === c.slug)) throw new Error(`Category "${c.slug}": its lead "${c.lead}" is not one of its projects`);
}
